SELECT p.gender, a.admittime, a.dischtime, a.deathtime, a.los, i.itemid, i.value, i.valueuom, d.diagnosis_code, d.diagnosis_name, COUNT(DISTINCT a.hadm_id) AS num_admissions, SUM(CASE WHEN a.deathtime IS NOT NULL THEN 1 ELSE 0 END) AS num_deaths, SUM(CASE WHEN i.itemid = '19757-3' THEN 1 ELSE 0 END) AS num_ckd, SUM(CASE WHEN i.itemid = '19757-4' THEN 1 ELSE 0 END) AS num_diabetes FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN chartevents i ON a.hadm_id = i.subject_id AND a.stay_id = i.stay_id JOIN diagnoses_icd d ON a.hadm_id = d.subject_id AND a.stay_id = d.stay_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 67 AND 77 AND d.diagnosis_code = '440.0' AND a.admittime <= i.charttime + INTERVAL '24 hours' AND (a.dischtime IS NULL OR a.dischtime >= i.charttime + INTERVAL '24 hours') AND (i.value IS NULL OR i.value NOT ILIKE '%death%') GROUP BY p.gender, a.admittime, a.dischtime, a.deathtime, a.los, i.itemid, i.value, d.diagnosis_code, d.diagnosis_name ORDER BY p.gender, a.admittime, a.dischtime, a.deathtime, a.los, i.itemid, i.value, d.diagnosis_code, d.diagnosis_name NULLS LAST;